import{_ as o,l as i,o as e,c as s,v as t,p as d,x as r,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"路径穿越与上传","description":"","frontmatter":{"title":"路径穿越与上传","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/path-traversal-upload.md","filePath":"cs/path-traversal-upload.md","lastUpdated":1789023840000}'),c={name:"cs/path-traversal-upload.md"};function E(_,a,u,m,A,f){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="路径穿越与上传" tabindex="-1">路径穿越与上传 <a class="header-anchor" href="#路径穿越与上传" aria-label="Permalink to &quot;路径穿越与上传&quot;">​</a></h1><div class="epigraph"><p>文件名若还能携带父目录或未检测的扩展名，存储根就不再是根。上传是同一问题的入口：内容类型与扩展必须由服务器决定，不能信客户端。</p><footer>—— 据 CWE-22；CWE-434；OWASP 文件上传</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/deserialization-attacks">反序列化</a>在对象图。缺口是<strong>文件系统名字</strong>。本课讲规范与根目录约束，不给读系统文件的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>拼接根路径与用户名未经规范化会逃出根。上传：双扩展、内容与 MIME 不一致、可执行目录。缺口是：规范化后必须仍在根内；文件不可执行。</p><h3 id="符号链接" tabindex="-1">符号链接 <a class="header-anchor" href="#符号链接" aria-label="Permalink to &quot;符号链接&quot;">​</a></h3><p>根内链接可指到根外。策略要禁跟随或 chroot。</p><p><span class="marginnote">CWE-22 与 CWE-434。禁止穿越 payload 教程。命令注入下一课是壳解释器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规范化后做前缀检查。上传存随机名于不可执行桶。下一课命令注入。</p>',12)),(e(),d(h,null,{default:r(()=>[p(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E7%94%A8%E6%88%B7%E6%96%87%E4%BB%B6%E5%90%8D%22%5D%20--%3E%20NORM%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20NORM%20--%3E%20ROOT%5B%22%E4%BB%8D%E5%9C%A8%E5%AD%98%E5%82%A8%E6%A0%B9%E5%86%85%3F%22%5D%0A%20%20UP%5B%22%E4%B8%8A%E4%BC%A0%22%5D%20--%3E%20EXEC%5B%22%E7%9B%AE%E5%BD%95%E4%B8%8D%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>完整中介：路径是客体名。逃根则 ACL 按错客体评。命令注入把字符串送进壳。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写穿越序列。命令注入下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对象图之后，路径是另一解释器。</li><li>规范化加根前缀；上传不可执行。</li><li>MIME 由服务器测，不信客户端。</li><li>下一课命令注入。</li><li>出处：CWE-22；CWE-434；OWASP。</li></ul>',8))])}const b=o(c,[["render",E]]);export{C as __pageData,b as default};
